using System;
using System.Collections.Generic;
using System.Linq;

// PROGRAM: Pembuktian Aliran Deferred Execution
static IEnumerable<int> GenerateNumbers()
{
    for (int i = 1; i <= 5; i++)
    {
        Console.WriteLine($"[GENERATOR] Memproduksi angka: {i}");
        yield return i;
    }
}

Console.WriteLine("Langkah 1: Membuat query LINQ...");
var query = GenerateNumbers().Where(n => {
    Console.WriteLine($"[FILTER] Mengecek angka: {n}");
    return n % 2 == 0;
});

Console.WriteLine("Langkah 2: Query sudah dibuat, tetapi belum ada angka yang diproduksi!");
Console.WriteLine("\nLangkah 3: Memulai iterasi foreach (Trigger Execution)...");

foreach (var item in query)
{
    Console.WriteLine($"[CONSUMER] Menerima angka genap: {item}\n");
}

